// n8n Code Node — "Run Once for Each Item" mode
// ============================================================
// Processes ONE row at a time from Get Row(s) in Sheet.
// Extracts the email and ONE specific question column,
// then formats it as the user prompt for the AI Agent.
//
// MODE: Run Once for Each Item
// ============================================================

// ┌─────────────────────────────────────────────────────────┐
// │  CONFIGURE: Set the keyword that identifies your        │
// │  question column. The code will find the column whose   │
// │  header CONTAINS this keyword (case-insensitive).       │
// └─────────────────────────────────────────────────────────┘

const EMAIL_COLUMN = "Email Address";

// Just put a unique keyword or phrase from the question header.
// No need to type the full header — partial match works.
const QUESTION_KEYWORD = $('Webhook').item.json.config.questionKeyword || "biggest challenge";

// ============================================================

const item = $input.item.json;

// Get email directly
const email = item[EMAIL_COLUMN] || '';

// Find the column whose header contains the keyword
const allKeys = Object.keys(item);
const questionKey = allKeys.find(
  key => key.toLowerCase().includes(QUESTION_KEYWORD.toLowerCase())
);

// If no match found, output an error message so you can debug
if (!questionKey) {
  return {
    json: {
      userPrompt: `ERROR: No column found matching keyword "${QUESTION_KEYWORD}". Available columns: ${allKeys.join(' | ')}`,
      email: email,
      answer: `COLUMN NOT FOUND — available: ${allKeys.join(', ')}`,
      research_question: 'ERROR'
    }
  };
}

const answer = item[questionKey] || '';
const researchQuestion = questionKey;  // The full column header IS the research question

// Build the user prompt — one response at a time
const userPrompt = `RESEARCH QUESTION: ${researchQuestion}

RESPONSES:
---
EMAIL: ${email}
ANSWER: ${answer}
---`;

return {
  json: {
    userPrompt: userPrompt,
    email: email,
    answer: answer,
    research_question: researchQuestion
  }
};

// n8n Code Node — Parse Phase 2 AI Agent Output for Google Sheets
// ============================================================
// Placed AFTER the AI Agent node, BEFORE Append Row in Sheet.
// Parses the agent's JSON response and flattens into columns:
// email | answer | verdict | initial_codes | explanation | verbatim
//
// MODE: Run Once for Each Item
// ============================================================

const item = $input.item.json;

// The agent output comes in the "output" field
const raw = item.output || item.text || item.response || '';

let parsed;
try {
  // Clean up markdown code fences if present
  let cleaned = raw.trim();
  if (cleaned.startsWith('```json')) {
    cleaned = cleaned.replace(/^```json\s*/, '').replace(/\s*```$/, '');
  } else if (cleaned.startsWith('```')) {
    cleaned = cleaned.replace(/^```\s*/, '').replace(/\s*```$/, '');
  }

  parsed = JSON.parse(cleaned);

  // If it's an array, take the first element (one item at a time)
  if (Array.isArray(parsed)) {
    parsed = parsed[0];
  }
} catch (e) {
  return {
    json: {
      email: 'PARSE_ERROR',
      answer: '',
      verdict: 'PARSE_ERROR',
      initial_codes: '',
      explanation: `Failed to parse agent output: ${raw.substring(0, 500)}`,
      verbatim: ''
    }
  };
}

// Return flat columns for Google Sheets — all from parsed agent response
return {
  json: {
    email: parsed.email || '',
    answer: parsed.answer || '',
    verdict: parsed.verdict || '',
    initial_codes: parsed.initial_codes || '',
    explanation: parsed.explanation || '',
    verbatim: parsed.verbatim || ''
  }
};

// n8n Code Node — Parse AI Agent JSON Output for Google Sheets
// ============================================================
// Placed AFTER the AI Agent node, BEFORE Append Row in Sheet.
// Extracts the structured fields from the agent's JSON response
// and flattens them into columns for Google Sheets.
//
// MODE: Run Once for Each Item
// ============================================================

const item = $input.item.json;

// The agent output comes in the "output" field (or "text" in some versions)
const raw = item.output || item.text || item.response || '';

// Parse the JSON array from the agent's response
let parsed;
try {
  // Clean up: remove any markdown code fences if present
  let cleaned = raw.trim();
  if (cleaned.startsWith('```json')) {
    cleaned = cleaned.replace(/^```json\s*/, '').replace(/\s*```$/, '');
  } else if (cleaned.startsWith('```')) {
    cleaned = cleaned.replace(/^```\s*/, '').replace(/\s*```$/, '');
  }

  parsed = JSON.parse(cleaned);

  // If it's an array, take the first element (since we process one item at a time)
  if (Array.isArray(parsed)) {
    parsed = parsed[0];
  }
} catch (e) {
  // If JSON parsing fails, return the raw output with an error flag
  return {
    json: {
      email: 'PARSE_ERROR',
      question: '',
      answer: '',
      verdict: 'PARSE_ERROR',
      explanation: `Failed to parse agent output: ${raw.substring(0, 500)}`
    }
  };
}

// Return flat columns for Google Sheets
// ALL fields come from the parsed agent response
return {
  json: {
    email: parsed.email || '',
    question: parsed.question || '',
    answer: parsed.answer || '',
    verdict: parsed.verdict || '',
    explanation: parsed.explanation || ''
  }
};

// n8n Code Node — Parse Phase 4 AI Agent Output for Google Sheets
// ============================================================
// ROBUST PARSER: Handles agents that output prose/thinking
// before the JSON. Extracts JSON from ```json``` fences,
// raw [...] blocks, or the full output.
//
// Columns: email | answer | theme_label | theme_rationale |
//          initial_codes_trail | verbatim_quotes
//
// MODE: Run Once for All Items
// ============================================================

const allItems = $input.all();
const raw = allItems[0].json.output || allItems[0].json.text || allItems[0].json.response || '';

// --- Extraction helpers ---

function tryParse(str) {
  try {
    return JSON.parse(str);
  } catch (_) {
    return null;
  }
}

function extractJSON(text) {
  if (typeof text === 'object' && text !== null) {
    return Array.isArray(text) ? text : [text];
  }

  const str = (typeof text === 'string') ? text : String(text);

  // Strategy 1: Try parsing the whole string as-is
  let result = tryParse(str.trim());
  if (result) return Array.isArray(result) ? result : [result];

  // Strategy 2: Extract from ```json ... ``` code fence
  const fenceMatch = str.match(/```json\s*([\s\S]*?)\s*```/);
  if (fenceMatch) {
    result = tryParse(fenceMatch[1].trim());
    if (result) return Array.isArray(result) ? result : [result];
  }

  // Strategy 3: Extract from ``` ... ``` code fence (no json tag)
  const genericFence = str.match(/```\s*([\s\S]*?)\s*```/);
  if (genericFence) {
    result = tryParse(genericFence[1].trim());
    if (result) return Array.isArray(result) ? result : [result];
  }

  // Strategy 4: Find the first [ and last ] — extract the JSON array
  const firstBracket = str.indexOf('[');
  const lastBracket = str.lastIndexOf(']');
  if (firstBracket !== -1 && lastBracket > firstBracket) {
    result = tryParse(str.substring(firstBracket, lastBracket + 1));
    if (result) return Array.isArray(result) ? result : [result];
  }

  // Strategy 5: Find first { and last } — single object
  const firstBrace = str.indexOf('{');
  const lastBrace = str.lastIndexOf('}');
  if (firstBrace !== -1 && lastBrace > firstBrace) {
    result = tryParse(str.substring(firstBrace, lastBrace + 1));
    if (result) return [result];
  }

  return null;
}

// --- Main ---

const parsed = extractJSON(raw);

if (!parsed) {
  return [{
    json: {
      email: 'PARSE_ERROR',
      answer: '',
      theme_label: '',
      theme_rationale: `Failed to extract JSON from agent output. First 500 chars: ${String(raw).substring(0, 500)}`,
      initial_codes_trail: '',
      verbatim_quotes: ''
    }
  }];
}

// Return ONE ROW PER UNIQUE THEME for Google Sheets
return parsed.map(entry => ({
  json: {
    email: entry.email || '',
    answer: entry.answer || '',
    theme_label: entry.theme_label || '',
    theme_rationale: entry.theme_rationale || '',
    initial_codes_trail: entry.initial_codes_trail || '',
    verbatim_quotes: entry.verbatim_quotes || ''
  }
}));

